<script>
export default {
  props: {
    history: {
      type: Array,
      required: true
    },
    currentDescription: {
      type: String,
      required: true
    }
  },
  emits: ['select-entry'],
  methods: {
    formatTime(timestamp) {
      const m = moment(timestamp)
      return m.isAfter(moment().subtract(1, 'day'))
        ? m.fromNow()
        : m.format('MM-DD HH:mm')
    },
    formatDate(timestamp) {
      const m = moment(timestamp)
      return m.format('YYYY-MM-DD HH:mm:ss')
    },
    getTooltip(entry) {
      const date = moment(entry.timestamp).format('YYYY-MM-DD HH:mm:ss')
      const msgCount = entry.message_ids?.length || 0
      const summary = entry.summary?.substring(0, 50)
      return `${date}\n${msgCount} messages\n${summary}`
    },
    isEntrySelected(entry) {
      return entry.timestamp === this.$parent.selectedHistoryEntry?.timestamp
    },
    selectEntry(entry) {
      this.$emit('select-entry', entry)
    }
  },
  computed: {
    selectedEntry() {
      return this.$parent.selectedHistoryEntry
    }
  }
}
</script>
